import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int64_t total_elements,
    int N,
    int IC,
    int ID,
    int IH,
    int IW,
    int OC,
    int OD,
    int OH,
    int OW,
    int KD,
    int KH,
    int KW,
    int stride_d,
    int stride_h,
    int stride_w,
    int pad_d,
    int pad_h,
    int pad_w,
    int groups,
    bool has_bias
) {
    int64_t linear_idx = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (linear_idx >= total_elements) {
        return;
    }

    int64_t t = linear_idx;

    const int ow = static_cast<int>(t % OW);
    t /= OW;
    const int oh = static_cast<int>(t % OH);
    t /= OH;
    const int od = static_cast<int>(t % OD);
    t /= OD;
    const int oc = static_cast<int>(t % OC);
    const int n = static_cast<int>(t / OC);

    const int out_channels_per_group = OC / groups;
    const int in_channels_per_group = IC / groups;
    const int group = oc / out_channels_per_group;
    const int oc_local = oc - group * out_channels_per_group;
    const int ic_start = group * in_channels_per_group;
    const int ic_end = ic_start + in_channels_per_group;

    float acc = has_bias ? bias[oc] : 0.0f;

    for (int kz = 0; kz < KD; ++kz) {
        const int id_numer = od + pad_d - kz;
        if (id_numer < 0 || id_numer % stride_d != 0) {
            continue;
        }
        const int id = id_numer / stride_d;
        if (id < 0 || id >= ID) {
            continue;
        }

        for (int ky = 0; ky < KH; ++ky) {
            const int ih_numer = oh + pad_h - ky;
            if (ih_numer < 0 || ih_numer % stride_h != 0) {
                continue;
            }
            const int ih = ih_numer / stride_h;
            if (ih < 0 || ih >= IH) {
                continue;
            }

            for (int kx = 0; kx < KW; ++kx) {
                const int iw_numer = ow + pad_w - kx;
                if (iw_numer < 0 || iw_numer % stride_w != 0) {
                    continue;
                }
                const int iw = iw_numer / stride_w;
                if (iw < 0 || iw >= IW) {
                    continue;
                }

                for (int ic = ic_start; ic < ic_end; ++ic) {
                    const int64_t input_idx =
                        (((static_cast<int64_t>(n) * IC + ic) * ID + id) * IH + ih) * IW + iw;

                    const int64_t weight_idx =
                        ((((static_cast<int64_t>(ic) * out_channels_per_group + oc_local) * KD + kz)
                          * KH + ky) * KW + kx);

                    acc += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    const int64_t output_idx =
        (((static_cast<int64_t>(n) * OC + oc) * OD + od) * OH + oh) * OW + ow;

    output[output_idx] = acc;
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_d,
    int stride_h,
    int stride_w,
    int pad_d,
    int pad_h,
    int pad_w,
    int output_pad_d,
    int output_pad_h,
    int output_pad_w,
    int groups
) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(input.dim() == 5, "input must have shape [N, C, D, H, W]");
    TORCH_CHECK(weight.dim() == 5, "weight must have shape [C_in, C_out/groups, Kd, Kh, Kw]");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(groups > 0, "groups must be positive");

    const int N = static_cast<int>(input.size(0));
    const int IC = static_cast<int>(input.size(1));
    const int ID = static_cast<int>(input.size(2));
    const int IH = static_cast<int>(input.size(3));
    const int IW = static_cast<int>(input.size(4));

    TORCH_CHECK(IC % groups == 0, "input channels must be divisible by groups");
    TORCH_CHECK(weight.size(0) == IC, "weight input-channel dimension mismatch");

    const int OC_per_group = static_cast<int>(weight.size(1));
    const int OC = OC_per_group * groups;

    const int KD = static_cast<int>(weight.size(2));
    const int KH = static_cast<int>(weight.size(3));
    const int KW = static_cast<int>(weight.size(4));

    TORCH_CHECK(output_pad_d < stride_d, "output_padding depth must be smaller than stride");
    TORCH_CHECK(output_pad_h < stride_h, "output_padding height must be smaller than stride");
    TORCH_CHECK(output_pad_w < stride_w, "output_padding width must be smaller than stride");

    const int OD = (ID - 1) * stride_d - 2 * pad_d + KD + output_pad_d;
    const int OH = (IH - 1) * stride_h - 2 * pad_h + KH + output_pad_h;
    const int OW = (IW - 1) * stride_w - 2 * pad_w + KW + output_pad_w;

    auto output = torch::empty(
        {N, OC, OD, OH, OW},
        input.options()
    );

    const bool has_bias = bias.numel() != 0;
    if (has_bias) {
        TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");
        TORCH_CHECK(bias.scalar_type() == torch::kFloat32, "bias must be float32");
        TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");
        TORCH_CHECK(bias.numel() == OC, "bias size mismatch");
    }

    const int64_t total_elements =
        static_cast<int64_t>(N) * OC * OD * OH * OW;

    constexpr int threads = 256;
    const int blocks = static_cast<int>((total_elements + threads - 1) / threads);

    cudaStream_t stream = at::cuda::getDefaultCUDAStream();

    conv_transpose3d_kernel<<<blocks, threads, 0, stream>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        total_elements,
        N,
        IC,
        ID,
        IH,
        IW,
        OC,
        OD,
        OH,
        OW,
        KD,
        KH,
        KW,
        stride_d,
        stride_h,
        stride_w,
        pad_d,
        pad_h,
        pad_w,
        groups,
        has_bias
    );

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
